 for(const key of ['databaseName','containerName'])assert.equal(state[key],policy.expectedDatabase[key]);
 assert.equal(state.metadata.APPLICATION_ID,134);assert.equal(state.metadata.WORKSPACE,policy.workspace);assert.equal(state.metadata.OWNER,policy.schema);assert.equal(state.metadata.ALIAS,policy.alias);
 assert.deepEqual(state.config,{enabled:1,workerEnabled:0,binding:null,heartbeat:null,schema:policy.schema,workspaceId:policy.workspaceId,applicationId:134});
 for(const key of ['activeRequests','activeRuns','activeImports','activeCleanups'])assert.equal(state[key],0);
 assert.equal(state.requests.length,1);assert.equal(state.requests[0].id,preservedRequestId);assert.equal(state.requests[0].state,'COMPLETED');assert.match(state.requests[0].runId,/^[a-f0-9]{32}$/);
