export async function claimControlUpdateAttempt(path,record){await writeFile(path,encode(record),{flag:'wx',flush:true});}
export async function executeControlUpdate({policy,policyBytes,baseline,backend,evidenceDir,attemptPath}){
 assertControlUpdatePolicy(policy,{execute:true});await mkdir(evidenceDir,{recursive:true});const result={kind:'native-control-update-only',applicationId:134,oldDefinitionHash:policy.oldDefinitionHash,newDefinitionHash:policy.newDefinitionHash,updateAttempted:false,verified:false,paidRequests:0,experimentLineage:false};let marked=false,resourcesClosed=true,stage='ADMISSION';
 try{
  try{await lstat(attemptPath);marked=true;throw Error('Permanent update attempt already exists');}catch(error){if(error.code!=='ENOENT')throw error;}
  assertControlUpdateState(policy,await backend.observe(),baseline);await backend.verifySources();stage='ARCHIVE';const archive=await backend.archive();assert.equal(archive.verified,true);assert.equal(archive.oldDefinitionHash,policy.oldDefinitionHash);assert.equal(archive.sqlExportSha256,baseline.sqlExportSha256);assert.match(archive.manifestSha256,sha);
  assertControlUpdateState(policy,await backend.observe(),baseline);await backend.verifySources();
  stage='PERMANENT_ATTEMPT';if(policyBytes)assert.deepEqual(JSON.parse(policyBytes.toString('utf8').replace(/^\uFEFF/,'')),policy);const record={kind:'native-control-update-attempt',attemptId:randomUUID().replaceAll('-',''),applicationId:134,oldDefinitionHash:policy.oldDefinitionHash,newDefinitionHash:policy.newDefinitionHash,policySha256:digest(policyBytes||encode(policy)),baselineSha256:policy.baselineSha256,archiveManifestSha256:archive.manifestSha256,createdAt:new Date().toISOString()};await claimControlUpdateAttempt(attemptPath,record);marked=true;
  assertControlUpdateState(policy,await backend.observe(),baseline);await backend.verifySources();stage='OWNER_SQLCL_UPDATE';result.updateAttempted=true;const imported=await backend.importApplication();assert.equal(imported.verified,true);assert.equal(imported.applicationId,134);
  stage='POST_IMPORT_READBACK';const after=await backend.observe();assertControlUpdateState(policy,after,baseline,{after:true});await backend.verifyNewAssets(after);await backend.verifySources();stage='AUTHENTICATED_READ_ONLY_WATCH';const runtime=await boundedRuntime(()=>backend.verifyRuntime(),policy.runtimeTimeoutMs);await assertRuntime(policy,runtime);assertControlUpdateState(policy,await backend.observe(),baseline,{after:true});result.runtime=runtime;result.statePreserved=true;result.verified=true;
 }catch(error){result.failureStage=stage;result.failure=/^(ORA|NJS)-\d+$/.test(error.code||'')?error.code:'CONTROL_UPDATE_INCOMPLETE';if(marked)result.noRetry=true;if(error.retainLock)resourcesClosed=false;}
 finally{
  for(const action of ['rollback','close'])try{await backend[action]();}catch{resourcesClosed=false;result.verified=false;result.resourceCleanupFailed=true;}
  if(resourcesClosed&&(result.verified||!marked)){try{await backend.releaseLock();}catch{result.verified=false;result.coordinatorLockRetained=true;result.noRetry=true;}}
  else{result.coordinatorLockRetained=true;result.noRetry=true;}
  result.permanentAttemptRetained=marked;result.state=result.verified?'VERIFIED':marked?'UNCERTAIN':'ADMISSION_REJECTED';result.observedAt=new Date().toISOString();await writeFile(join(evidenceDir,'update-result.json'),encode(result),{flag:'wx',flush:true});
 }return {...result,evidenceDir};
}

