async function openConnection(oracle){
 let timer,late=false;const pending=oracledb.getConnection({user:oracle.user,password:oracle.password,connectString:oracle.connectString});
 pending.then(connection=>{if(late)void closeApplicationResources({database:connection}).catch(()=>{});},()=>{});
 try{const db=await Promise.race([pending,new Promise((_,reject)=>{timer=setTimeout(()=>{late=true;const error=Error('Owner connection acquisition uncertain');error.retainLock=true;reject(error);},10000);})]);try{db.callTimeout=10000;}catch(error){try{await closeApplicationResources({database:db});}catch{}error.retainLock=true;throw error;}return db;}finally{clearTimeout(timer);}
}
